const [view, setView] = useState('media');

<ButtonGroup size="sm">
  {views.map(({ value, label, icon: Icon }) => (
    <Button
      key={value}
      variant={view === value ? 'secondary' : 'ghost'}
      startContent={<Icon size={15} />}
      onPress={() => setView(value)}
    >
      {label}
    </Button>
  ))}
</ButtonGroup>
